"""
apply_day7.py  -  ONE FILE that upgrades your production-rag project to Day 7.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day7.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day7\\
  2. Writes all Day 1-7 code, tests, scripts, evals and docs into this folder
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
  4. Runs  pip install -r requirements.txt
  5. Runs  python scripts\\verify_day7.py  (tests + live hostile-document + rate-limit checks)

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without live checks (free)
    --force         run even if this does not look like a production-rag folder
"""

